"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.20571",title:"Any Time, Any Space: A World-State-Centric Framework for Agentic Video Generation",up:169,href:"https://arxiv.org/abs/2610.20571",abstract:"Long-form agentic video generation must turn a screenplay into shots that remain spatially and temporally consistent across nonconsecutive requests. Passing prompts or recent frames between shots does not provide a shared spatial frame for revisiting a scene or a time-indexed record for replaying an earlier event. We present Any Time, Any Space (ATAS), which compiles a screenplay into shot requests with explicit location, camera, and event-time references. Before generation, it retrieves relevant evidence from a scene memory of registered static geometry and an event memory of dynamic observat",pdfUrl:"https://arxiv.org/pdf/2610.20571",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.20584",title:"Player-1: Learning to Play from Synthetic Experience",up:119,href:"https://arxiv.org/abs/2610.20584",abstract:"Computer-use agents have demonstrated strong capabilities in interpreting screens and executing keyboard and mouse actions. However, games, with their visually rich worlds and diverse mechanics, remain challenging and offer a demanding next step toward general digital control. Current game-agent learning pipelines often rely on large-scale demonstrations with limited coverage of dynamic game states, while scalable environments for interactive training remain difficult to obtain. We introduce Player-1, a post-training framework for learning game control beyond demonstrations through synthetic e",pdfUrl:"https://arxiv.org/pdf/2610.20584",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.19698",title:"RuleTrek: Benchmarking Agentic Rule Reasoning in Complex Scenarios",up:49,href:"https://arxiv.org/abs/2610.19698",abstract:"Large language models (LLMs) increasingly tackle complex real-world tasks in specialized domains. However, identifying and correctly applying domain-specific rules remains challenging when scenario information is distributed across multiple files. Existing rule-reasoning benchmarks typically represent scenarios using only a few factual statements, simplifying the identification and application of relevant rules. To address this gap, this paper introduces \\textbf{RuleTrek}, a multi-domain benchmark for agentic rule reasoning in complex scenarios. Its rule-grounded construction pipeline extracts",pdfUrl:"https://arxiv.org/pdf/2610.19698",primaryCategory:"cs.AI",published:"2026-10-14T00:00:00Z"},{id:"2610.20572",title:"Recovering Reliable Supervision via Critique-Guided On-Policy Distillation",up:49,href:"https://arxiv.org/abs/2610.20572",abstract:"On-policy distillation (OPD) trains a student model on its own rollouts with token-level supervision from a teacher, assuming that the teacher can reach a correct answer from any prefix the student writes. We call this property the recoverability of the teacher and show it fails on incorrect rollouts: the teacher follows student errors, although it recognizes them. We propose CriticOPD, using error recognition to restore recoverability. The teacher critiques an incorrect rollout, allowing the student to rewrite its solution following the error. The resulting output, including the critique as p",pdfUrl:"https://arxiv.org/pdf/2610.20572",primaryCategory:"cs.LG",published:"2026-10-14T00:00:00Z"},{id:"2610.20399",title:"Cortex: Consolidating Context into Parametric Memory",up:48,href:"https://arxiv.org/abs/2610.20399",abstract:"Context can improve large language model performance, but these gains may be lost after context removal. Inspired by biological systems consolidation, we formulate Memory Consolidation (MC) as internalizing these gains while preserving non-target capabilities, connecting context-specified editing, skill learning, and behavioral steering under a common objective. We introduce a five-task-family testbed measuring consolidation and retention under single, batch, and sequential updates. We propose Cortex, which generates prospective queries to anticipate uses of context and distills context-condit",pdfUrl:"https://arxiv.org/pdf/2610.20399",primaryCategory:"cs.CL",published:"2026-10-14T00:00:00Z"},{id:"2610.19820",title:"ActionOPD: Distilling Decisions, Not Tokens",up:45,href:"https://arxiv.org/abs/2610.19820",abstract:"Distilling capable language-model agents into smaller models requires aligning the student's behavior with the teacher's. This raises a fundamental question: at which states and at what granularity should this alignment be performed? Offline imitation provides dense but token-specific supervision and can suffer from state-distribution mismatch. Token-level on-policy distillation (OPD) addresses this mismatch but typically requires teacher token probabilities and compatible tokenization. We argue that semantic actions provide a natural unit of supervision for agent distillation. We introduce Ac",pdfUrl:"https://arxiv.org/pdf/2610.19820",primaryCategory:"cs.AI",published:"2026-10-14T00:00:00Z"},{id:"2610.20344",title:"Doc2Harness: Benchmarking LLMs on Long-Horizon Harness Engineering of Coding Agents",up:39,href:"https://arxiv.org/abs/2610.20344",abstract:"Agents driven by large language models are increasingly deployed on long-horizon tasks, where they use tools and modify real workspaces. How well they perform depends as much on the harness around the model as on the model itself. Existing benchmarks measure downstream task success under a fixed harness, leaving harness engineering itself unexplored. We propose Doc2Harness, a two-stage benchmark that evaluates long-horizon harness engineering directly. In Stage 1, a build model operating inside a fixed builder harness receives an interface-only contract skeleton and a development document that",pdfUrl:"https://arxiv.org/pdf/2610.20344",primaryCategory:"cs.SE",published:"2026-10-14T00:00:00Z"},{id:"2610.19366",title:"Seeing, Maintaining, and Learning: The Evolution of Multimodal Agent Memory",up:31,href:"https://arxiv.org/abs/2610.19366",abstract:"Multimodal models and agents have emerged to enable AI systems to learn from and interact with the real world more like humans by integrating information across multiple modalities. However, enabling multimodal agents to continually acquire useful information from complex, heterogeneous multimodal data remains a significant challenge as they move toward long-horizon tasks and lifelong settings. Addressing this challenge requires effective memory mechanisms that can maintain continuity across sessions, adapt to changing users and environments, and refine memory-management policies through accum",pdfUrl:"https://arxiv.org/pdf/2610.19366",primaryCategory:"cs.AI",published:"2026-10-14T01:11:57Z"},{id:"2610.14448",title:"KV4-RL: Unlocking Faster Asynchronous Rollouts for RLVR with INT4 KV Cache Quantization",up:26,href:"https://arxiv.org/abs/2610.14448",abstract:"Asynchronous rollout improves the efficiency of reinforcement learning with verifiable rewards (RLVR) by reducing under-utilization during long-tail generation. Sustained concurrency also concentrates context processing into fewer decode steps, increasing the KV workload per step. We characterize this \\emph{KV concentration} and find that KV cache quantization delivers substantially greater acceleration than weight-only and weight-activation quantization in our matched-workload comparisons. However, INT4 KV rollout can degrade learning even with token-level truncated importance sampling (TIS).",pdfUrl:"https://arxiv.org/pdf/2610.14448",primaryCategory:"cs.LG",published:"2026-10-10T00:00:00Z"},{id:"2610.13521",title:"Beyond Domain-Routed Supervision: Cross-Teacher Guarding for Multi-Teacher On-Policy Distillation",up:24,href:"https://arxiv.org/abs/2610.13521",abstract:"Multi-teacher on-policy distillation (MOPD) extends on-policy distillation (OPD) by routing domain-specific data to specialized teachers, integrating their capabilities through dense token-level supervision on student-generated trajectories. However, domain routing only distinguishes the supervision sources for different domains; updates from all domains still act on shared parameters. When teachers differ substantially in response style and domain expertise, supervision that is effective in isolation may still lead to persistent gradient conflicts and capability degradation during joint optim",pdfUrl:"https://arxiv.org/pdf/2610.13521",primaryCategory:"cs.AI",published:"2026-10-09T00:00:00Z"},{id:"2610.15542",title:"Apertus 1.5: From Open Text Models to Open Multimodal Reasoners",up:24,href:"https://arxiv.org/abs/2610.15542",abstract:"Language models are becoming infrastructure, and infrastructure built in the open, by public institutions, on documented data, is the alternative to dependence on a few providers; Apertus shows this is viable at scale. Apertus 1.5 extends the fully open Apertus family from text to multimodal reasoning. Continued pretraining of the Apertus 1.0 models, on 4T additional tokens for the 8B and 2T for the 70B, adds image and audio understanding and extends the context window fourfold to 262,144 tokens; multimodality enters through the tokenizer, the language-model head remains restricted to text, an",pdfUrl:"https://arxiv.org/pdf/2610.15542",primaryCategory:"cs.CL",published:"2026-10-11T00:00:00Z"},{id:"2610.18861",title:"Hybrid Reasoning Agents",up:20,href:"https://arxiv.org/abs/2610.18861",abstract:"How can we build an agent that thinks beyond human language, yet still acts through it in the external environment? Modern LLM agents still reason and interact through text, while latent reasoning offers an efficient internal medium but lacks native tool access and reasoning transparency. We bridge these two directions with Hybrid Reasoning Agents (HybridAgents), which dynamically navigate between latent reasoning and text-based interaction throughout a unified generation process. Architecturally, a lightweight HybridLink enables seamless transitions between text and latent modes, while the ag",pdfUrl:"https://arxiv.org/pdf/2610.18861",primaryCategory:"cs.CL",published:"2026-10-13T00:00:00Z"},{id:"2610.20442",title:"Towards Agentic Robots: Model, Data, Environment, and Harness",up:19,href:"https://arxiv.org/abs/2610.20442",abstract:"Foundation models are driving a paradigm shift in robotic intelligence, moving beyond low-level action prediction to goal-directed orchestration of data collection, model training, task planning, and real-world execution. We characterize this emerging paradigm as an agentic robots, in which agents reason over human instructions, interact with robotic environments, rectify execution errors autonomously, and dynamically adjust operational strategies. Although this field develops fast, current studies are not well connected. Researchers have no consistent view of how to combine different agentic ",pdfUrl:"https://arxiv.org/pdf/2610.20442",primaryCategory:"cs.RO",published:"2026-10-14T00:00:00Z"},{id:"2610.19789",title:"More Methods, Better Agents? A Reality Check on Self-Distillation in Agentic Reinforcement Learning",up:15,href:"https://arxiv.org/abs/2610.19789",abstract:"Self-distillation in agentic reinforcement learning has produced a growing number of methods. However, existing evaluations often reuse published baseline scores under differing experimental conditions, provide few direct comparisons among contemporaneous methods, and give limited attention to training stability and computational cost. These limitations obscure the source of reported gains and the practical strengths and weaknesses of competing methods. Costly agent training further motivates a common basis for comparison. To address these gaps, we compare ten representative methods against GR",pdfUrl:"https://arxiv.org/pdf/2610.19789",primaryCategory:"cs.CL",published:"2026-10-14T00:00:00Z"},{id:"2610.04781",title:"Super-Resolution in The Right Latent Space: A Frozen Vision-Foundation Substrate",up:13,href:"https://arxiv.org/abs/2610.04781",abstract:"In an image latent space, the embeddings of high-resolution, natural, and sharp images form a manifold. Degradation of high-resolution images pushes their embeddings off this manifold. Real-world super-resolution (SR) then becomes the task of mapping the degraded embedding back onto this manifold --- not anywhere on the manifold, but to the point that preserves what the input still carries, both its semantics and pixel details. Every published method implements this mapping in a reconstruction-oriented latent space or pixel space. We claim these spaces are the wrong substrates for SR. Low-reso",pdfUrl:"https://arxiv.org/pdf/2610.04781",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"2610.02089",title:"HumanoidToolBench: Benchmarking Humanoid Tool Use from Selection to Mobile Execution",up:11,href:"https://arxiv.org/abs/2610.02089",abstract:"As robotic hardware and learning methods advance, humanoids need tools to perform tasks beyond their inherent physical limits. Successful tool use requires selecting a suitable tool and coordinating manipulation and, when needed, locomotion to complete the task. Existing benchmarks do not jointly evaluate these capabilities on a humanoid. We introduce HumanoidToolBench, an 18-task benchmark spanning three scenarios, three execution levels, and two tool-set modes, together with ToolBook, a dataset of 3.1k demonstrations collected in simulation and on a real Unitree G1. Evaluation of seven polic",pdfUrl:"https://arxiv.org/pdf/2610.02089",primaryCategory:"cs.RO",published:"2026-10-01T00:00:00Z"},{id:"2610.19560",title:"τ-Emotion-Bench: Exposing the Interaction Fragility of LLM Agents through Real-World User Emotions",up:9,href:"https://arxiv.org/abs/2610.19560",abstract:"In long-horizon tool-calling tasks, LLM agents can fail not only because of tool-use errors, but also because of ineffective interaction with users. Yet existing benchmarks largely assume cooperative and behaviorally stable users, leaving the effect of emotional variation on agent reliability underexplored. We introduce $τ$-Emotion-Bench, a ten-domain benchmark for evaluating tool-calling agents under controlled emotion-conditioned user interactions while preserving the underlying task objective. To scale both benchmark construction and agent training, we introduce Tracer, a scalable agentic d",pdfUrl:"https://arxiv.org/pdf/2610.19560",primaryCategory:"cs.AI",published:"2026-10-14T04:19:15Z"},{id:"2610.15725",title:"SkillMarker: A KGW-Based Watermarking Method for Agent Skill Ownership Verification",up:8,href:"https://arxiv.org/abs/2610.15725",abstract:"Agent skills encode operational procedures and domain expertise as reusable knowledge assets, yet their distribution in plaintext exposes them to unauthorized copying and leakage. However, practical mechanisms for skill ownership verification and leakage tracing remain underdeveloped. Watermark embedding before distribution offers a potential solution, but structured, compact skill instructions impose stringent requirements for factual and procedural accuracy. To address these challenges, we introduce SkillMarker, a KGW-based watermarking method that jointly targets functionality preservation ",pdfUrl:"https://arxiv.org/pdf/2610.15725",primaryCategory:"cs.CR",published:"2026-10-11T00:00:00Z"},{id:"2610.18284",title:"Efficient Scene-Text Refinement via Pixel-Space Grouped Image Generation",up:6,href:"https://arxiv.org/abs/2610.18284",abstract:"Generated images often have coherent layouts and visual content, yet local errors in small text and complex characters still limit their readability and practical use. Scene-text refinement requires accuracy, preservation, and efficiency. Existing methods based on variational autoencoders (VAEs) can lose fine strokes during reconstruction, while full-image editing can shift background colors. In this work, we introduce PixText, a model that formulates local text refinement as grouped image generation in pixel space. Conditioned on the original image, PixText generates only the target regions, ",pdfUrl:"https://arxiv.org/pdf/2610.18284",primaryCategory:"cs.CV",published:"2026-10-13T00:00:00Z"},{id:"2610.19525",title:"Diagnosing and Correcting Reward Hacking in Verifiable Instruction Following",up:6,href:"https://arxiv.org/abs/2610.19525",abstract:"Verifiable instruction-following benchmarks emphasize output-constraint satisfaction but can overlook whether responses meaningfully answer the underlying request, creating an evaluation blind spot. We show that frontier models can receive full credit for responses with little substantive answer content. Using the same verifier-based criterion as a training reward can induce reward hacking, as publicly released checkpoints exhibit higher constraint satisfaction but lower response quality after reinforcement learning with verifiable rewards. To address this reward hacking, we introduce CALIF, a",pdfUrl:"https://arxiv.org/pdf/2610.19525",primaryCategory:"cs.LG",published:"2026-10-14T03:42:59Z"},{id:"2606.24472",title:"G^3VLA: Geometric Inductive Bias for Vision-Language-Action Models",up:5,href:"https://arxiv.org/abs/2606.24472",abstract:"Vision-language-action (VLA) models have rapidly advanced generalist robot manipulation by harnessing the semantic knowledge of pretrained vision-language backbones. However, their visual representations are typically grounded in 2D image coordinates rather than calibrated camera geometry. This limitation is especially pronounced in multi-camera systems, where views are coupled by known intrinsics and extrinsics but processed as independent images. We propose G$^3$VLA, a camera-aware geometric module that injects calibrated structure into the visual-token stream of a pretrained VLA without alt",pdfUrl:"https://arxiv.org/pdf/2606.24472",primaryCategory:"cs.RO",published:"2026-10-14T00:00:00Z"},{id:"2610.14774",title:"ProgAgent: Learning Tool Orchestration through Programmatic Training",up:5,href:"https://arxiv.org/abs/2610.14774",abstract:"Large language models (LLMs) are increasingly expected to orchestrate diverse tools over long-horizon tasks. Existing agents typically use Direct Tool Calling (DTC), where the model invokes tools sequentially, and tool responses accumulate in the model context, which can lead to context rot and orchestration breakdown. In contrast, Programmatic Tool Calling (PTC) invokes tools through executable code and stores intermediate results in runtime variables rather than appending them to the context. Prior work has explored PTC mainly as an inference-time optimization, but its benefits for agentic t",pdfUrl:"https://arxiv.org/pdf/2610.14774",primaryCategory:"cs.AI",published:"2026-10-10T00:00:00Z"},{id:"2610.20256",title:"Long-Horizon RL Needs Muon",up:4,href:"https://arxiv.org/abs/2610.20256",abstract:"Long-horizon agents must coordinate reasoning, tool use, and environment feedback over extended interactions. Learning from sparse outcome rewards requires weighting trajectories of different lengths and updating the policy while rollouts are still being collected. We examine a single-rollout asynchronous recipe combining Muon, token-averaged loss, truncated importance sampling, and auxiliary length and tool-error penalties. Single-rollout sampling allows asynchronous learning without waiting for multiple trajectories for the same issue. We study optimizer choices and recipe components for rep",pdfUrl:"https://arxiv.org/pdf/2610.20256",primaryCategory:"cs.LG",published:"2026-10-14T00:00:00Z"},{id:"2610.14261",title:"BigCell: Generating Gigapixel Whole-Slide Images",up:3,href:"https://arxiv.org/abs/2610.14261",abstract:"Whole-slide images (WSIs) are gigapixel-scale digital scans of histopathology tissue and serve as the primary basis for cancer diagnosis. Existing histopathology generative models operate at the patch scale, producing fixed-size tiles of at most 1024$\\times$1024 pixels which encompass only a small fraction of the WSI. In contrast, text reports for clinical diagnoses and slide-level diagnostic labels -- the supervision that exists at scale -- operate at the whole-slide level. We present BigCell, the first approach to generate coherent whole-slide histopathology images at native gigapixel resolu",pdfUrl:"https://arxiv.org/pdf/2610.14261",primaryCategory:"cs.CV",published:"2026-10-09T00:00:00Z"},{id:"W7171516088",title:"SpecBox: Speculative Sandbox Scheduling for Efficient LLM Agent Serving",up:0,href:"https://doi.org/10.48550/arxiv.2607.23933",crossrefDoi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7171516088",crossrefIssued:"2026-08-24"},{id:"W7204032694",title:"Do Not Let Sandboxes Sit Idle: Cross-Agent Sandbox Re-allocation for LLM Agents",up:0,href:"https://doi.org/10.1007/978-981-92-4805-6_13",doi:"https://doi.org/10.1007/978-981-92-4805-6_13",year:2026,openalexId:"https://openalex.org/W7204032694"},{id:"W7221316450",title:"FHIR-AgentEval: a modular sandbox for benchmarking clinical LLM agents with memory-augmented configurations",up:0,href:"https://doi.org/10.1038/s41746-026-03348-0",doi:"https://doi.org/10.1038/s41746-026-03348-0",year:2026,openalexId:"https://openalex.org/W7221316450"}]}}]);